using System.Security.Claims;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using TechnifyERP.Application.Doubts;
namespace TechnifyERP.Areas.Admin.Controllers;[Area("Admin"),Authorize(Roles="SuperAdmin")]public sealed class DoubtsController(IDoubtService service):Controller{public async Task<IActionResult>Index(CancellationToken ct)=>View(await service.GetAllAsync(ct));[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Answer(int id,string answer,CancellationToken ct){await service.AnswerAdminAsync(User.FindFirstValue(ClaimTypes.NameIdentifier)!,id,answer,ct);return RedirectToAction(nameof(Index));}}
